-- Subject set with the capability booleans: the same list with an EXISTS per row per transition.
SELECT Id, SectorId, ClientId, KindId, Title, Brief, Hazard, Fee, Deadline, RequiredCertId, BookedBy, AssignedSquadronId, StatusId, Notes, ARRAY<BOOL>[((`Missions`.`StatusId` IN ('claimed') AND EXISTS (SELECT 1 FROM `SquadronMemberships` `ca4` WHERE `ca4`.`UserId` = 'lead' AND `ca4`.`SquadronId` = `Missions`.`AssignedSquadronId` AND EXISTS (SELECT 1 FROM `Squadrons` `ca5` WHERE `ca5`.`Id` = `ca4`.`SquadronId` AND EXISTS (SELECT 1 FROM `Wings` `ca6` WHERE `ca6`.`Id` = `ca5`.`WingId` AND `ca6`.`SectorId` = 'anvil'))))), (`Missions`.`StatusId` IN ('underway')), (`Missions`.`StatusId` IN ('on_hold')), (`Missions`.`StatusId` IN ('open')), (`Missions`.`StatusId` = 'underway')] AS zzCapabilityChecks FROM Missions WHERE (`Missions`.`SectorId` = 'anvil') AND (EXISTS (SELECT 1 FROM `SquadronMemberships` `ca1` WHERE `ca1`.`UserId` = 'lead' AND `ca1`.`SquadronId` = `Missions`.`AssignedSquadronId` AND EXISTS (SELECT 1 FROM `Squadrons` `ca2` WHERE `ca2`.`Id` = `ca1`.`SquadronId` AND EXISTS (SELECT 1 FROM `Wings` `ca3` WHERE `ca3`.`Id` = `ca2`.`WingId` AND `ca3`.`SectorId` = 'anvil'))) OR `Missions`.`BookedBy` = 'lead') ORDER BY `Deadline` ASC, `Id` ASC LIMIT 26
